function extractFromTranscript(transcriptPath) {
  let content;
  try { content = fs.readFileSync(transcriptPath, 'utf8'); } catch { return null; }
  if (!content) return null;

  const lines = content.split('\n').filter(Boolean);
  const toolsUsed = new Set();
  const filesModified = new Set();
  const filesRead = new Set();
  let userMessageCount = 0;

  for (const line of lines) {
    try {
      const entry = JSON.parse(line);

      if (entry.type === 'user' || entry.role === 'user' || (entry.message && entry.message.role === 'user')) {
        userMessageCount++;
      }

      // Direct tool_use entries
      if (entry.type === 'tool_use' || entry.tool_name) {
        const name = entry.tool_name || entry.name || '';
        if (name) toolsUsed.add(name);
        const fp = (entry.tool_input && entry.tool_input.file_path) || (entry.input && entry.input.file_path) || '';
        if (fp) {
          if (name === 'Edit' || name === 'Write') filesModified.add(fp);
          else if (name === 'Read') filesRead.add(fp);
        }
      }

      // Tool uses inside assistant message content blocks
      if (entry.type === 'assistant' && entry.message && Array.isArray(entry.message.content)) {
        for (const block of entry.message.content) {
          if (block.type === 'tool_use') {
            const name = block.name || '';
            if (name) toolsUsed.add(name);
            const fp = (block.input && block.input.file_path) || '';
            if (fp) {
              if (name === 'Edit' || name === 'Write') filesModified.add(fp);
              else if (name === 'Read') filesRead.add(fp);
            }
          }
        }
      }
    } catch { /* skip unparseable */ }
  }

  if (userMessageCount === 0) return null;

  return {
    toolsUsed: Array.from(toolsUsed).slice(0, 20),
    filesModified: Array.from(filesModified).slice(0, 30),
    filesRead: Array.from(filesRead).slice(0, 30),
    userMessageCount,
  };
}

