function toRepoRelative(filePath) {
  const normalized = filePath.replace(/\\/g, '/');
  const rootNormalized = REPO_ROOT.replace(/\\/g, '/');
  if (normalized.toLowerCase().startsWith(rootNormalized.toLowerCase())) {
    return normalized.slice(rootNormalized.length).replace(/^\//, '');
  }
  return normalized;
}

function deriveDomains(relPaths) {
  const domains = new Set();
  for (const p of relPaths) {
    const libMatch = p.match(/^library\/(.+?)\/(?:terms|texts|domains)\//);
    if (libMatch) { domains.add(libMatch[1]); continue; }
    const libIdx = p.match(/^library\/(.+?)\/_index\.md$/);
    if (libIdx) { domains.add(libIdx[1]); continue; }
    const opsMatch = p.match(/^operations\/([^/]+)\//);
    if (opsMatch) { domains.add(`operations/${opsMatch[1]}`); }
  }
  return Array.from(domains).sort();
}

function deriveTasks(relPaths) {
  const tasks = new Set();
  for (const p of relPaths) {
    const m = p.match(/^operations\/[^/]+\/records\/tasks\/(.+)\.md$/);
    if (m) tasks.add(m[1]);
  }
  return Array.from(tasks).sort();
}

